import { createSlice } from "@reduxjs/toolkit";
import * as action from "../actions/currentProfileActions";

function normalizePayload(payload) {
  // If payload is already in {status, data} form
  if (payload && typeof payload === "object" && "status" in payload && "data" in payload) {
    return payload;
  }
  // If payload looks like an Axios response
  if (payload && payload.status && payload.data !== undefined) {
    return { status: payload.status, data: payload.data };
  }
  // Fallback: treat payload as raw data, assume success
  return { status: 200, data: payload };
}

export const currentProfileSlicer = createSlice({
  name: "currentProfile",
  initialState: {
    data: null,
    bookmarks: null,
    loading: false,
    errors: null,
  },
  extraReducers: {
    [action.signUp.pending]: (state) => {
      state.loading = true;
    },
    [action.signIn.pending]: (state) => {
      state.loading = true;
    },
    [action.getCurrentProfile.pending]: (state) => {
      state.loading = true;
    },
    [action.signUp.fulfilled]: (state, action) => {
      const { status, data } = normalizePayload(action.payload);
      if (status === 200) {
        state.data = data;
        state.errors = null;
      } else {
        state.errors = data.errors || "Unknown error";
      }
      state.loading = false;
    },
    [action.signIn.fulfilled]: (state, action) => {
      const { status, data } = normalizePayload(action.payload);
      if (status === 200) {
        state.data = data;
        state.errors = null;
      } else {
        state.errors = data.errors || "Unknown error";
      }
      state.loading = false;
    },
    [action.signOut.fulfilled]: (state, action) => {
      const { status } = normalizePayload(action.payload);
      if (status === 200) {
        state.data = null;
      }
    },
    [action.getCurrentProfile.fulfilled]: (state, action) => {
      const { status, data } = normalizePayload(action.payload);
      if (status === 200) {
        state.data = data;
      }
      state.loading = false;
    },
    [action.addBookmark.fulfilled]: (state, action) => {
      const { status, data } = normalizePayload(action.payload);
      if (status === 200) {
        state.data = data;
      }
    },
    [action.removeBookmark.fulfilled]: (state, action) => {
      const { status, data } = normalizePayload(action.payload);
      if (status === 200) {
        state.data = data;
      }
    },
    [action.editProfile.fulfilled]: (state, action) => {
      const { status, data } = normalizePayload(action.payload);
      if (status === 200) {
        state.data = data;
      }
    },
    [action.uploadAvatar.fulfilled]: (state, action) => {
      const { status, data } = normalizePayload(action.payload);
      if (status === 200) {
        state.data = data;
      }
    },
    [action.getBookmarks.fulfilled]: (state, action) => {
      const { status, data } = normalizePayload(action.payload);
      if (status === 200) {
        state.bookmarks = data;
      }
    },
  },
});

export default currentProfileSlicer.reducer;
